package org.com.sharekhan.analysis;
import org.com.sharekhan.config.SecurityConfig;import org.com.sharekhan.service.AdminUserDetailsService;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.MediaType;import java.util.*;
import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ThesisController.class) @Import(SecurityConfig.class)
class ThesisSecurityTest {
 @Autowired MockMvc mvc;@MockBean ThesisOwner owner;@MockBean ThesisService service;@MockBean AdminUserDetailsService users;
 void identity(){when(owner.resolve(any())).thenAnswer(inv->"USER:"+(((org.springframework.security.core.Authentication)inv.getArgument(0)).getName().equals("alice")?1:2));}
 String create="{\"requestId\":\"12345678-1234-4234-8234-123456789abc\",\"symbol\":\"RELIANCE\",\"thesisType\":\"GROWTH_MOMENTUM\",\"thesis\":\"Research thesis\",\"entryCondition\":\"Condition\",\"invalidation\":\"Invalidation\"}";
 @Test void readAndWriteAlwaysUseServerResolvedOwner()throws Exception{identity();for(String role:new String[]{"USER","ADMIN"}){mvc.perform(get("/api/stock-analysis/journal?owner=USER:999").with(user("alice").roles(role))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post("/api/stock-analysis/journal?owner=USER:999").with(user("alice").roles(role)).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(create)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}verify(service,times(2)).book("USER:1");verify(service,times(2)).create(eq("USER:1"),any());}
 @Test void anonymousOtherRolesAndMissingCsrfCannotReadOrWrite()throws Exception{mvc.perform(get("/api/stock-analysis/journal")).andExpect(status().isUnauthorized());mvc.perform(get("/api/stock-analysis/journal").with(user("x").roles("OTHER"))).andExpect(status().isForbidden());for(String path:new String[]{"/api/stock-analysis/journal","/api/stock-analysis/journal/id/transition","/api/stock-analysis/journal/id/review","/api/stock-analysis/journal/id/postmortem"})mvc.perform(post(path).with(user("alice").roles("USER")).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());mvc.perform(put("/api/stock-analysis/journal/id").with(user("alice").roles("USER")).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());verifyNoInteractions(service,owner);}
 @Test void secondIdentityIsNeverSubstitutedByRecordOrRequestOwner()throws Exception{identity();mvc.perform(get("/api/stock-analysis/journal/12345678-1234-4234-8234-123456789abc?owner=USER:1").with(user("bob").roles("ADMIN"))).andExpect(status().isOk());verify(service).get("USER:2","12345678-1234-4234-8234-123456789abc");}
 @Test void journalCannotBeDeletedAndGetCannotTransition()throws Exception{identity();mvc.perform(delete("/api/stock-analysis/journal/id").with(user("alice").roles("USER")).with(csrf())).andExpect(status().isMethodNotAllowed());mvc.perform(get("/api/stock-analysis/journal/id/transition").with(user("alice").roles("USER"))).andExpect(status().isMethodNotAllowed());verifyNoInteractions(service);}
}
